colossal_glowcap_spire.source:
export const envelope = [35, 54, 35];

export default function build(api) {
  const SX = envelope[0];
  const SY = envelope[1];
  const SZ = envelope[2];
  const seatY = 9;
  const cx = 17;
  const cz = 17;

  // 3D block buffer
  const world = new Array(SX * SY * SZ).fill(null);

  function getBase(str) {
    if (!str) return "minecraft:oak_planks";
    return str.split("[")[0];
  }

  function withState(baseStr, state) {
    const base = getBase(baseStr);
    return `${base}[${state}]`;
  }

  function setBlock(x, y, z, block) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x < 0 || x >= SX || y < 0 || y >= SY || z < 0 || z >= SZ) return;
    world[x + y * SX + z * SX * SY] = block;
  }

  function getBlock(x, y, z) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x < 0 || x >= SX || y < 0 || y >= SY || z < 0 || z >= SZ) return null;
    return world[x + y * SX + z * SX * SY];
  }

  // Palette resolution from theme
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodDoor = api.theme.wood.door || "minecraft:spruce_door";
  const roofSolid = api.theme.roof.solid || woodPlanks;
  const roofStairs = api.theme.roof.stairs || woodStairs;

  // Stem curvature & radius profile
  function getStemCenter(y) {
    const ry = y - seatY;
    const offX = Math.sin(ry * 0.11) * 1.0;
    const offZ = Math.cos(ry * 0.09) * 0.7;
    return [cx + offX, cz + offZ];
  }

  function getStemRadius(y) {
    const ry = y - seatY;
    if (ry < 0) {
      return 6.0 + Math.min(4.0, -ry * 0.6);
    }
    let r = 3.6;
    if (ry <= 10) {
      r += 2.4 * Math.pow((10 - ry) / 10, 1.8);
    }
    if (ry >= 22) {
      r += 4.2 * Math.pow((ry - 22) / 14, 2.2);
    }
    return r;
  }

  // 1. GENERATE THE CENTRAL FUNGAL STEM
  for (let y = 0; y <= 38; y++) {
    const [scx, scz] = getStemCenter(y);
    const baseR = getStemRadius(y);

    for (let x = 0; x < SX; x++) {
      for (let z = 0; z < SZ; z++) {
        const dx = x - scx;
        const dz = z - scz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        const angle = Math.atan2(dz, dx);

        // Organic fungal ribs along the stalk
        const rib = 0.55 * Math.sin(5 * angle + (y - seatY) * 0.18) + 0.35 * Math.cos(3 * angle - (y - seatY) * 0.12);
        const rEff = baseR + rib;

        if (dist <= rEff) {
          // Leave interior rooms and central shaft hollowed
          const isInterior1 = (y >= 10 && y <= 14 && dist <= 2.2);
          const isInterior2 = (y >= 19 && y <= 23 && dist <= 2.2);
          const isInterior3 = (y >= 34 && y <= 38 && dist <= 3.2);
          const isCentralShaft = (y >= 10 && y <= 38 && dist <= 1.2);

          if (isInterior1 || isInterior2 || isInterior3 || isCentralShaft) {
            continue;
          }

          // Bioluminescent vertical veins
          const veinPattern = Math.sin(angle * 4 + y * 0.4) * Math.cos(y * 0.25);
          const isVein = (dist >= rEff - 1.2) && (veinPattern > 0.68);

          let block;
          if (isVein) {
            block = (y % 3 === 0) ? "minecraft:ochre_froglight" : "minecraft:shroomlight";
          } else if (dist < rEff - 1.2) {
            block = "minecraft:mushroom_stem";
          } else {
            const n = Math.sin(x * 12.3 + y * 7.1 + z * 5.4);
            block = (n > 0.35) ? woodStripped : "minecraft:mushroom_stem";
          }

          setBlock(x, y, z, block);
        }
      }
    }
  }

  // 2. BUTTRESS ROOTS & TERRAIN CONFORMANCE (Rule 6)
  const rootAngles = [0.35, 1.55, 2.85, 4.15, 5.35];
  for (const baseAngle of rootAngles) {
    for (let d = 3.5; d <= 13.5; d += 0.5) {
      const curl = 0.06 * (14 - d);
      const rx = cx + d * Math.cos(baseAngle + curl);
      const rz = cz + d * Math.sin(baseAngle + curl);
      const ix = Math.round(rx);
      const iz = Math.round(rz);
      if (ix < 1 || ix >= SX - 1 || iz < 1 || iz >= SZ - 1) continue;

      const gh = seatY + api.heightAt(ix, iz);
      const heightAboveGround = Math.max(0, Math.round(4.0 * Math.pow(1 - d / 14, 1.4)));
      const topY = gh + heightAboveGround;
      const width = (d < 7) ? 1.4 : (d < 11 ? 0.9 : 0.5);

      for (let ox = -1; ox <= 1; ox++) {
        for (let oz = -1; oz <= 1; oz++) {
          if (ox * ox + oz * oz <= width * width) {
            const colX = ix + ox;
            const colZ = iz + oz;
            if (colX < 0 || colX >= SX || colZ < 0 || colZ >= SZ) continue;
            const colGh = seatY + api.heightAt(colX, colZ);
            const minY = Math.min(colGh, seatY);

            for (let y = Math.max(0, minY); y <= Math.min(SY - 1, topY); y++) {
              const isNodule = (y === topY && (d % 3 < 1));
              const rBlock = isNodule ? "minecraft:shroomlight" : "minecraft:mushroom_stem";
              setBlock(colX, y, colZ, rBlock);
            }
          }
        }
      }
    }
  }

  // Ensure all stem footprint columns solidly meet the ground
  for (let x = 0; x < SX; x++) {
    for (let z = 0; z < SZ; z++) {
      const gh = seatY + api.heightAt(x, z);
      if (getBlock(x, seatY, z) !== null) {
        const startY = Math.max(0, Math.min(gh, seatY));
        const endY = Math.max(gh, seatY);
        for (let y = startY; y <= endY; y++) {
          if (!getBlock(x, y, z)) {
            setBlock(x, y, z, "minecraft:mushroom_stem");
          }
        }
      }
    }
  }

  // 3. COLOSSAL GLOWING MUSHROOM CAP
  const spotOffsets = [
    [0.2, 4.5], [1.2, 5.0], [2.1, 4.0], [3.0, 5.5], [4.1, 4.2], [5.0, 5.0],
    [0.7, 9.0], [1.8, 9.5], [2.6, 10.0], [3.6, 8.5], [4.6, 9.2], [5.8, 10.5]
  ];

  for (let y = 34; y <= 52; y++) {
    for (let x = 0; x < SX; x++) {
      for (let z = 0; z < SZ; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        const angle = Math.atan2(dz, dx);

        const rMax = 14.5 + 0.8 * Math.cos(6 * angle) + 0.4 * Math.sin(3 * angle);
        if (dist > rMax) continue;

        const normD = dist / 15.0;
        const yTop = 52.0 - 14.5 * Math.pow(normD, 1.6);
        const yBottom = 33.5 + 4.5 * Math.pow(normD, 0.7) - 1.5 * Math.pow(normD, 2.5);

        if (y <= yTop && y >= yBottom) {
          // Hollow upper chamber
          if (y >= 34 && y <= 38 && dist <= 3.2) {
            continue;
          }

          const distToTop = yTop - y;
          const distToBottom = y - yBottom;

          // Bioluminescent polka-dot spots on toadstool dome
          let isSpot = false;
          for (let i = 0; i < spotOffsets.length; i++) {
            const spX = cx + spotOffsets[i][1] * Math.cos(spotOffsets[i][0]);
            const spZ = cz + spotOffsets[i][1] * Math.sin(spotOffsets[i][0]);
            const dSpot = Math.sqrt((x - spX) * (x - spX) + (z - spZ) * (z - spZ));
            if (dSpot < 1.6) {
              isSpot = true;
              break;
            }
          }

          if (distToTop <= 1.2) {
            setBlock(x, y, z, isSpot ? "minecraft:shroomlight" : "minecraft:red_mushroom_block");
          } else if (distToBottom <= 1.0) {
            // Radial gills under cap
            const gillVal = Math.sin(angle * 24);
            setBlock(x, y, z, gillVal > 0.2 ? "minecraft:mushroom_stem" : "minecraft:shroomlight");
          } else {
            setBlock(x, y, z, (distToTop <= 2.2 && isSpot) ? "minecraft:ochre_froglight" : "minecraft:mushroom_stem");
          }
        }

        // Hanging spore droplets around cap rim
        if (dist >= rMax - 1.2 && dist <= rMax) {
          if (Math.abs(y - Math.round(yBottom)) <= 0.5) {
            const dropRand = Math.sin(x * 17.1 + z * 31.4);
            if (dropRand > 0.45) {
              const dropLen = 1 + Math.floor((dropRand - 0.45) * 5);
              for (let dy = 1; dy <= dropLen; dy++) {
                const vy = y - dy;
                if (vy >= 30 && !getBlock(x, vy, z)) {
                  setBlock(x, vy, z, (dy === dropLen) ? "minecraft:shroomlight" : "minecraft:chain[axis=y]");
                }
              }
            }
          }
        }
      }
    }
  }

  // 4. VILLAGE ARCHITECTURE: SPIRAL DECKS, BRIDGES & LOOKOUTS

  // --- TIER 1: LOWER DECK & NORTH GRAND STAIRWAY (Y = 14) ---
  const t1Y = seatY + 5;
  const [scx1, scz1] = getStemCenter(t1Y);
  const sr1 = getStemRadius(t1Y);

  for (let x = 0; x < SX; x++) {
    for (let z = 0; z < SZ; z++) {
      const dx = x - scx1;
      const dz = z - scz1;
      const dist = Math.sqrt(dx * dx + dz * dz);
      const angle = Math.atan2(dz, dx);

      if (angle >= -Math.PI * 0.55 && angle <= Math.PI * 0.55) {
        if (dist >= sr1 - 0.5 && dist <= sr1 + 3.5) {
          setBlock(x, t1Y, z, woodPlanks);

          // Support corbels
          if (dist > sr1 + 1.2) {
            setBlock(x, t1Y - 1, z, withState(woodStairs, "facing=north,half=top,shape=straight"));
            if (dist > sr1 + 2.5) {
              setBlock(x, t1Y - 2, z, woodFence);
            }
          }

          // Railing
          if (dist > sr1 + 2.7) {
            setBlock(x, t1Y + 1, z, woodFence);
            if ((x + z) % 4 === 0) {
              setBlock(x, t1Y + 2, z, "minecraft:lantern[hanging=false]");
            }
          }
        }
      }
    }
  }

  // North entrance ramp descending to ground
  const startZ = Math.round(scz1 - sr1 - 1);
  for (let z = startZ; z >= 2; z--) {
    const prog = (startZ - z) / (startZ - 2);
    const targetX = cx;
    const ghCenter = seatY + api.heightAt(targetX, z);
    const curY = Math.max(ghCenter, Math.round(t1Y - prog * (t1Y - (seatY + api.heightAt(targetX, 2)))));

    for (let ox = -1; ox <= 1; ox++) {
      const px = targetX + ox;
      const gh = seatY + api.heightAt(px, z);
      setBlock(px, curY, z, woodPlanks);
      for (let sy = Math.max(0, gh); sy < curY; sy++) {
        setBlock(px, sy, z, (ox === 0) ? woodLog : woodPlanks);
      }
    }
    setBlock(targetX - 2, curY + 1, z, woodFence);
    setBlock(targetX + 2, curY + 1, z, woodFence);
    if (z % 3 === 0) {
      setBlock(targetX - 2, curY + 2, z, "minecraft:lantern[hanging=false]");
      setBlock(targetX + 2, curY + 2, z, "minecraft:lantern[hanging=false]");
    }
  }

  // Stairs Tier 1 -> Tier 2
  for (let step = 0; step <= 14; step++) {
    const progress = step / 14;
    const sy = Math.round(14 + progress * 8);
    const ang = progress * Math.PI;
    const [scx, scz] = getStemCenter(sy);
    const sr = getStemRadius(sy);
    const dist = sr + 1.2;

    for (let w = 0; w <= 1; w++) {
      const wx = Math.round(scx + (dist + w) * Math.cos(ang));
      const wz = Math.round(scz + (dist + w) * Math.sin(ang));
      setBlock(wx, sy, wz, woodPlanks);
      setBlock(wx, sy - 1, wz, woodFence);
      if (w === 1) {
        setBlock(wx, sy + 1, wz, woodFence);
      }
    }
  }

  // --- TIER 2: MID BALCONY & WITCH HUT (Y = 22) ---
  const t2Y = 22;
  const [scx2, scz2] = getStemCenter(t2Y);
  const sr2 = getStemRadius(t2Y);

  for (let x = 0; x < SX; x++) {
    for (let z = 0; z < SZ; z++) {
      const dx = x - scx2;
      const dz = z - scz2;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dx < 1.0) {
        if (dist >= sr2 - 0.5 && dist <= sr2 + 4.2) {
          setBlock(x, t2Y, z, woodPlanks);

          if (dist > sr2 + 1.5) {
            setBlock(x, t2Y - 1, z, withState(woodStairs, "facing=south,half=top,shape=straight"));
            setBlock(x, t2Y - 2, z, woodFence);
          }

          if (dist > sr2 + 3.4) {
            setBlock(x, t2Y + 1, z, woodFence);
            if ((x + z) % 3 === 0) {
              setBlock(x, t2Y - 1, z, "minecraft:chain[axis=y]");
              setBlock(x, t2Y - 2, z, "minecraft:shroomlight");
            }
          }
        }
      }
    }
  }

  // Witch cottage structure
  const hutMinX = Math.round(scx2 - 6);
  const hutMaxX = Math.round(scx2 - 2);
  const hutMinZ = Math.round(scz2 - 3);
  const hutMaxZ = Math.round(scz2 + 3);

  for (let hx = hutMinX; hx <= hutMaxX; hx++) {
    for (let hz = hutMinZ; hz <= hutMaxZ; hz++) {
      for (let hy = t2Y; hy <= t2Y + 5; hy++) {
        const isCorner = (hx === hutMinX || hx === hutMaxX) && (hz === hutMinZ || hz === hutMaxZ);
        const isWall = (hx === hutMinX || hx === hutMaxX || hz === hutMinZ || hz === hutMaxZ);

        if (hy === t2Y) {
          setBlock(hx, hy, hz, woodPlanks);
        } else if (hy === t2Y + 5) {
          setBlock(hx, hy, hz, roofSolid);
        } else if (hy === t2Y + 4) {
          setBlock(hx, hy, hz, withState(roofStairs, "facing=north,half=bottom,shape=straight"));
        } else if (isWall) {
          if (isCorner) {
            setBlock(hx, hy, hz, woodLog);
          } else if (hx === hutMaxX && hz === Math.round(scz2)) {
            setBlock(hx, hy, hz, "minecraft:air");
          } else if (hz === hutMinZ && hx === Math.round((hutMinX + hutMaxX) / 2) && hy === t2Y + 2) {
            setBlock(hx, hy, hz, woodFence);
          } else {
            setBlock(hx, hy, hz, woodPlanks);
          }
        }
      }
    }
  }

  // Stairs Tier 2 -> Tier 3
  for (let step = 0; step <= 16; step++) {
    const progress = step / 16;
    const sy = Math.round(22 + progress * 9);
    const ang = Math.PI + progress * Math.PI;
    const [scx, scz] = getStemCenter(sy);
    const sr = getStemRadius(sy);
    const dist = sr + 1.2;

    for (let w = 0; w <= 1; w++) {
      const wx = Math.round(scx + (dist + w) * Math.cos(ang));
      const wz = Math.round(scz + (dist + w) * Math.sin(ang));
      setBlock(wx, sy, wz, woodPlanks);
      setBlock(wx, sy - 1, wz, woodFence);
      if (w === 1) {
        setBlock(wx, sy + 1, wz, woodFence);
      }
    }
  }

  // --- TIER 3: UPPER LOOKOUT RING (Y = 31) ---
  const t3Y = 31;
  const [scx3, scz3] = getStemCenter(t3Y);
  const sr3 = getStemRadius(t3Y);

  for (let x = 0; x < SX; x++) {
    for (let z = 0; z < SZ; z++) {
      const dx = x - scx3;
      const dz = z - scz3;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dist >= sr3 - 0.5 && dist <= sr3 + 2.8) {
        setBlock(x, t3Y, z, woodPlanks);

        if (dist > sr3 + 1.2) {
          setBlock(x, t3Y - 1, z, woodFence);
        }

        if (dist > sr3 + 2.0) {
          setBlock(x, t3Y + 1, z, woodFence);
        }
      }
    }
  }

  const hangOffsets = [[3.5, 0], [-3.5, 0], [0, 3.5], [0, -3.5]];
  for (const [hx, hz] of hangOffsets) {
    const lx = Math.round(scx3 + hx);
    const lz = Math.round(scz3 + hz);
    setBlock(lx, t3Y - 1, lz, "minecraft:chain[axis=y]");
    setBlock(lx, t3Y - 2, lz, "minecraft:chain[axis=y]");
    setBlock(lx, t3Y - 3, lz, "minecraft:shroomlight");
  }

  // --- TIER 4: UNDER-CAP BALCONIES (Y = 34..36) ---
  const dirOffsets = [
    [0, -4.2], [0, 4.2], [4.2, 0], [-4.2, 0]
  ];
  for (const [dox, doz] of dirOffsets) {
    const bx = Math.round(cx + dox);
    const bz = Math.round(cz + doz);
    for (let ox = -1; ox <= 1; ox++) {
      for (let oz = -1; oz <= 1; oz++) {
        setBlock(bx + ox, 34, bz + oz, woodPlanks);
        setBlock(bx + ox, 35, bz + oz, (ox === 0 && oz === 0) ? "minecraft:air" : woodFence);
      }
    }
    setBlock(Math.round(cx + dox * 0.7), 34, Math.round(cz + doz * 0.7), woodPlanks);
    setBlock(Math.round(cx + dox * 0.7), 35, Math.round(cz + doz * 0.7), "minecraft:air");
    setBlock(Math.round(cx + dox * 0.7), 36, Math.round(cz + doz * 0.7), "minecraft:air");
  }

  // 5. INTERIOR ROOMS & CENTRAL ACCESS LADDER
  const interiors = [
    {
      min: [cx - 2, 10, cz - 2],
      max: [cx + 2, 14, cz + 2],
      kind: "hall"
    },
    {
      min: [cx - 2, 19, cz - 2],
      max: [cx + 2, 23, cz + 2],
      kind: "quarters"
    },
    {
      min: [cx - 3, 34, cz - 3],
      max: [cx + 3, 38, cz + 3],
      kind: "watchtower"
    }
  ];

  // Lay solid wooden floor courses one block below interior min.y
  for (let ox = -2; ox <= 2; ox++) {
    for (let oz = -2; oz <= 2; oz++) {
      setBlock(cx + ox, 9, cz + oz, woodPlanks);
      setBlock(cx + ox, 18, cz + oz, woodPlanks);
    }
  }
  for (let ox = -3; ox <= 3; ox++) {
    for (let oz = -3; oz <= 3; oz++) {
      setBlock(cx + ox, 33, cz + oz, woodPlanks);
    }
  }

  // Clear room volumes
  for (const room of interiors) {
    for (let x = room.min[0]; x <= room.max[0]; x++) {
      for (let y = room.min[1]; y <= room.max[1]; y++) {
        for (let z = room.min[2]; z <= room.max[2]; z++) {
          if (x === cx + 1 && z === cz + 1) continue;
          setBlock(x, y, z, "minecraft:air");
        }
      }
    }
  }

  // Lower hall entrance doorway facing North
  setBlock(cx, 10, cz - 3, "minecraft:air");
  setBlock(cx, 11, cz - 3, "minecraft:air");
  setBlock(cx, 12, cz - 3, "minecraft:air");

  // Continuous internal access ladder
  for (let y = 10; y <= 38; y++) {
    if (!getBlock(cx + 1, y, cz + 2)) {
      setBlock(cx + 1, y, cz + 2, "minecraft:mushroom_stem");
    }
    setBlock(cx + 1, y, cz + 1, "minecraft:ladder[facing=north]");
  }

  // 6. EMIT FINAL BLOCK BUFFER
  for (let x = 0; x < SX; x++) {
    for (let y = 0; y < SY; y++) {
      for (let z = 0; z < SZ; z++) {
        const blk = world[x + y * SX + z * SX * SY];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  return {
    name: "Colossal Glowcap Spire",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      door: [cx, t1Y, cz - 3]
    },
    interiors
  };
}

