export const envelope = [13, 18, 13];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const inst = (api.instance.index || 0) % 6;

  // Safe voxel setter with envelope bounds clamping
  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  // Robust block-state applicator
  function applyState(baseBlock, newStates) {
    if (!baseBlock) return "";
    let id = baseBlock;
    const stateMap = {};
    const bracketIndex = baseBlock.indexOf("[");
    if (bracketIndex !== -1) {
      id = baseBlock.slice(0, bracketIndex);
      const inner = baseBlock.slice(bracketIndex + 1, -1);
      for (const pair of inner.split(",")) {
        const [k, v] = pair.split("=");
        if (k && v) stateMap[k.trim()] = v.trim();
      }
    }
    for (const [k, v] of Object.entries(newStates)) {
      stateMap[k] = v;
    }
    const pairs = Object.entries(stateMap).map(([k, v]) => `${k}=${v}`);
    return pairs.length > 0 ? `${id}[${pairs.join(",")}]` : id;
  }

  // Palette resolution from world theme with robust fallbacks
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodDoor = api.theme?.wood?.door || "minecraft:spruce_door";
  const stonePlinth = api.theme?.ground?.plinth || api.theme?.stone?.primary || "minecraft:mossy_cobblestone";

  // Fungal & bioluminescent elements
  const stemBlock = "minecraft:mushroom_stem";
  const redCapBlock = "minecraft:red_mushroom_block";
  const brownCapBlock = "minecraft:brown_mushroom_block";
  const shroomlight = "minecraft:shroomlight";
  const chainBlock = "minecraft:chain[axis=y]";
  const regularLantern = "minecraft:lantern[hanging=true]";
  const soulLantern = "minecraft:soul_lantern[hanging=true]";
  const activeLantern = (inst % 2 === 1) ? soulLantern : regularLantern;

  // Stilt timber choice per instance
  const stiltLog = (inst === 1 || inst === 4) ? woodStripped : woodLog;

  // Ground conformity helper (seat plane is y = 4)
  function getGroundY(x, z) {
    const h = api.heightAt(x, z);
    return Math.max(0, Math.min(17, 4 + Math.round(h)));
  }

  function buildGroundColumn(x, z, topY, mainBlock, baseBlock) {
    const gy = getGroundY(x, z);
    const startY = Math.min(gy, 4);
    for (let y = startY; y <= topY; y++) {
      if (y <= gy) {
        set(x, y, z, baseBlock || mainBlock);
      } else {
        set(x, y, z, mainBlock);
      }
    }
  }

  function hangLantern(x, y, z, lanternType) {
    if (x < 0 || x >= sizeX || z < 0 || z >= sizeZ) return;
    set(x, y, z, chainBlock);
    if (y - 1 >= 0) {
      set(x, y - 1, z, lanternType);
    }
  }

  // --- 1. GROUND FOOTINGS & STILTS (Ground to y = 7) ---
  const stiltPositions = [
    [3, 3], [9, 3], // Front main stilts
    [3, 8], [9, 8], // Rear main stilts
    [4, 1], [8, 1], // Balcony support posts
    [6, 1]          // Ladder support post
  ];

  for (const [sx, sz] of stiltPositions) {
    const topY = (sx === 6 && sz === 1) ? 8 : 7;
    buildGroundColumn(sx, sz, topY, applyState(stiltLog, { axis: "y" }), stonePlinth);
  }

  // --- 2. GIANT FUNGAL STALK (Ground to y = 14) ---
  const stalkColumns = [
    [5, 8], [6, 8], [7, 8],
    [5, 9], [6, 9], [7, 9],
    [6, 10]
  ];

  for (const [stx, stz] of stalkColumns) {
    buildGroundColumn(stx, stz, 14, stemBlock, stonePlinth);
  }

  // Knee braces beneath the deck frame at y = 6
  set(3, 6, 4, applyState(woodStairs, { facing: "south", half: "top" }));
  set(4, 6, 3, applyState(woodStairs, { facing: "east", half: "top" }));
  set(9, 6, 4, applyState(woodStairs, { facing: "south", half: "top" }));
  set(8, 6, 3, applyState(woodStairs, { facing: "west", half: "top" }));
  set(3, 6, 7, applyState(woodStairs, { facing: "north", half: "top" }));
  set(4, 6, 8, applyState(woodStairs, { facing: "east", half: "top" }));
  set(9, 6, 7, applyState(woodStairs, { facing: "north", half: "top" }));
  set(8, 6, 8, applyState(woodStairs, { facing: "west", half: "top" }));

  // Balcony knee braces
  set(4, 6, 1, applyState(woodStairs, { facing: "north", half: "top" }));
  set(8, 6, 1, applyState(woodStairs, { facing: "north", half: "top" }));

  // --- 3. SUSPENSION LADDER (Ground to y = 7 at North Front) ---
  const ladderBottomY = getGroundY(6, 0);
  for (let ly = ladderBottomY; ly <= 7; ly++) {
    set(6, ly, 0, "minecraft:ladder[facing=south]");
  }

  // --- 4. DECK FRAMEWORK & BALCONY (y = 7 and y = 8) ---
  // Structural support beams at y = 7
  for (let x = 3; x <= 9; x++) {
    set(x, 7, 3, applyState(woodLog, { axis: "x" }));
    set(x, 7, 8, applyState(woodLog, { axis: "x" }));
  }
  for (let z = 3; z <= 8; z++) {
    set(3, 7, z, applyState(woodLog, { axis: "z" }));
    set(9, 7, z, applyState(woodLog, { axis: "z" }));
  }
  for (let z = 1; z <= 2; z++) {
    set(4, 7, z, applyState(woodLog, { axis: "z" }));
    set(6, 7, z, applyState(woodLog, { axis: "z" }));
    set(8, 7, z, applyState(woodLog, { axis: "z" }));
  }

  // Floor deck at y = 8
  for (let x = 3; x <= 9; x++) {
    for (let z = 3; z <= 8; z++) {
      set(x, 8, z, woodPlanks);
    }
  }
  // Front balcony platform at y = 8
  for (let x = 4; x <= 8; x++) {
    for (let z = 1; z <= 2; z++) {
      set(x, 8, z, woodPlanks);
    }
  }

  // Under-dwelling glowing hanging lantern
  set(6, 7, 5, applyState(woodLog, { axis: "z" }));
  hangLantern(6, 6, 5, activeLantern);

  // Balcony railings at y = 9
  set(4, 9, 1, woodFence);
  set(5, 9, 1, woodFence);
  // (6, 9, 1) left open for ladder walk-in access
  set(7, 9, 1, woodFence);
  set(8, 9, 1, woodFence);
  set(4, 9, 2, woodFence);
  set(8, 9, 2, woodFence);
  set(4, 10, 1, woodFence);
  set(8, 10, 1, woodFence);

  // --- 5. HUT WALLS & EXTERIOR ENCLOSURE (y = 9 to 12) ---
  // Corner posts
  for (let y = 9; y <= 11; y++) {
    set(3, y, 3, applyState(woodLog, { axis: "y" }));
    set(9, y, 3, applyState(woodLog, { axis: "y" }));
    set(3, y, 8, applyState(woodLog, { axis: "y" }));
    set(9, y, 8, applyState(woodLog, { axis: "y" }));
  }

  // North wall (z = 3) with doorway and windows
  for (let y = 9; y <= 11; y++) {
    set(4, y, 3, woodPlanks);
    set(5, y, 3, y === 10 ? woodFence : woodPlanks);
    set(7, y, 3, y === 10 ? woodFence : woodPlanks);
    set(8, y, 3, woodPlanks);
  }
  // Doorway at (6, 9..10, 3)
  set(6, 9, 3, applyState(woodDoor, { facing: "north", half: "lower", hinge: "left", open: "false" }));
  set(6, 10, 3, applyState(woodDoor, { facing: "north", half: "upper", hinge: "left", open: "false" }));
  set(6, 11, 3, applyState(woodStairs, { facing: "south", half: "top" }));

  // West wall (x = 3)
  for (let y = 9; y <= 11; y++) {
    for (let z = 4; z <= 7; z++) {
      set(3, y, z, (z === 5 && y === 10) ? woodFence : woodPlanks);
    }
  }

  // East wall (x = 9)
  for (let y = 9; y <= 11; y++) {
    for (let z = 4; z <= 7; z++) {
      set(9, y, z, (z === 6 && y === 10) ? woodFence : woodPlanks);
    }
  }

  // South wall (z = 8) embedded with fungal stalk
  for (let y = 9; y <= 11; y++) {
    set(4, y, 8, woodPlanks);
    set(5, y, 8, stemBlock);
    set(6, y, 8, stemBlock);
    set(7, y, 8, stemBlock);
    set(8, y, 8, woodPlanks);
  }

  // Ceiling beams and roof infill at y = 12
  for (let x = 3; x <= 9; x++) {
    set(x, 12, 3, applyState(woodLog, { axis: "x" }));
    set(x, 12, 8, applyState(woodLog, { axis: "x" }));
  }
  for (let z = 3; z <= 8; z++) {
    set(3, 12, z, applyState(woodLog, { axis: "z" }));
    set(9, 12, z, applyState(woodLog, { axis: "z" }));
    set(6, 12, z, applyState(woodLog, { axis: "z" }));
  }
  for (let x = 4; x <= 8; x++) {
    for (let z = 4; z <= 7; z++) {
      set(x, 12, z, woodPlanks);
    }
  }

  // --- 6. GIANT MUSHROOM CANOPY ROOF (y = 12 to 17) ---
  const cx = 6.0;
  const cz = 5.5;

  if (inst === 0) {
    // Variation 0: Domed Red Amanita with bioluminescent spots
    const rByY = { 12: 5.4, 13: 5.6, 14: 5.0, 15: 4.2, 16: 3.0, 17: 1.6 };
    for (let y = 12; y <= 17; y++) {
      const r = rByY[y];
      for (let x = 0; x <= 12; x++) {
        for (let z = 0; z <= 12; z++) {
          const d = Math.hypot(x - cx, z - cz);
          if (d <= r) {
            if (y === 12) {
              if (d >= 2.5) set(x, y, z, stemBlock);
            } else {
              const isOuter = d > r - 1.2;
              const isSpot = isOuter && (((x + z) % 3 === 0 && (x * z) % 2 === 0) || Math.sin(x * 2.5 + z * 3.1 + y) > 0.6);
              set(x, y, z, isSpot ? shroomlight : redCapBlock);
            }
          }
        }
      }
    }
    hangLantern(2, 11, 2, regularLantern);
    hangLantern(10, 11, 2, regularLantern);
    hangLantern(2, 11, 9, regularLantern);
    hangLantern(10, 11, 9, regularLantern);

  } else if (inst === 1) {
    // Variation 1: Tiered Brown Shelf Mushroom
    function drawShelf(scx, scz, yMin, yMax, radius) {
      for (let y = yMin; y <= yMax; y++) {
        const r = (y === yMin) ? radius : radius - 0.4;
        for (let x = 0; x <= 12; x++) {
          for (let z = 0; z <= 12; z++) {
            const d = Math.hypot(x - scx, z - scz);
            if (d <= r) {
              if (y === yMin && d >= 1.8) {
                set(x, y, z, stemBlock);
              } else {
                const isRim = d > r - 0.9;
                const isGlow = isRim && ((x + z) % 3 === 0);
                set(x, y, z, isGlow ? shroomlight : brownCapBlock);
              }
            }
          }
        }
      }
    }
    drawShelf(6.0, 5.5, 12, 13, 5.6);
    drawShelf(5.5, 5.0, 14, 15, 4.3);
    drawShelf(6.5, 6.0, 16, 17, 2.8);

    hangLantern(3, 11, 2, soulLantern);
    hangLantern(9, 11, 2, soulLantern);
    hangLantern(6, 13, 1, soulLantern);

  } else if (inst === 2) {
    // Variation 2: Bioluminescent Twin-Cap Perch
    function drawDome(dcx, dcz, yMin, yMax, baseRadius, capBlock, withSpots) {
      for (let y = yMin; y <= yMax; y++) {
        const progress = (y - yMin) / (yMax - yMin + 1);
        const r = baseRadius * Math.sqrt(Math.max(0.01, 1 - progress * progress));
        for (let x = 0; x <= 12; x++) {
          for (let z = 0; z <= 12; z++) {
            const d = Math.hypot(x - dcx, z - dcz);
            if (d <= r) {
              const isOuter = d > r - 1.1;
              const isSpot = withSpots && isOuter && ((x * 3 + z * 5 + y) % 4 === 0);
              set(x, y, z, isSpot ? shroomlight : capBlock);
            }
          }
        }
      }
    }
    drawDome(4.5, 4.0, 13, 16, 4.0, redCapBlock, true);
    drawDome(7.5, 7.0, 14, 17, 3.8, brownCapBlock, false);

    for (let x = 4; x <= 8; x++) {
      for (let z = 4; z <= 7; z++) {
        set(x, 13, z, woodPlanks);
      }
    }
    hangLantern(2, 12, 2, regularLantern);
    hangLantern(10, 13, 8, soulLantern);

  } else if (inst === 3) {
    // Variation 3: Witch-Hat Conical Spire
    for (let y = 12; y <= 17; y++) {
      const r = 5.4 - (y - 12) * 0.85;
      for (let x = 0; x <= 12; x++) {
        for (let z = 0; z <= 12; z++) {
          const d = Math.hypot(x - cx, z - cz);
          if (d <= r) {
            if (y === 17) {
              set(x, y, z, shroomlight);
            } else if (y === 12) {
              set(x, y, z, applyState(woodStairs, { facing: (x >= cx ? "west" : "east"), half: "top" }));
            } else {
              set(x, y, z, redCapBlock);
            }
          }
        }
      }
    }
    hangLantern(1, 10, 5, soulLantern);
    hangLantern(11, 10, 5, soulLantern);
    hangLantern(6, 10, 11, soulLantern);

  } else if (inst === 4) {
    // Variation 4: Leaning Canopy Hermitage
    for (let y = 12; y <= 17; y++) {
      const lx = cx + (y - 12) * 0.4;
      const lz = cz - (y - 12) * 0.25;
      const r = 5.5 - (y - 12) * 0.8;
      for (let x = 0; x <= 12; x++) {
        for (let z = 0; z <= 12; z++) {
          const d = Math.hypot(x - lx, z - lz);
          if (d <= r) {
            if (y === 12) {
              set(x, y, z, stemBlock);
            } else if (y === 17) {
              set(x, y, z, shroomlight);
            } else {
              const isGlow = (d > r - 1.0) && ((x + y + z) % 4 === 0);
              set(x, y, z, isGlow ? shroomlight : brownCapBlock);
            }
          }
        }
      }
    }
    hangLantern(3, 11, 1, soulLantern);
    hangLantern(9, 11, 7, soulLantern);

  } else {
    // Variation 5: Wide Spotted Umbrella
    const rByY = { 12: 5.6, 13: 5.8, 14: 5.0, 15: 4.0, 16: 2.8, 17: 1.5 };
    for (let y = 12; y <= 17; y++) {
      const r = rByY[y];
      for (let x = 0; x <= 12; x++) {
        for (let z = 0; z <= 12; z++) {
          const d = Math.hypot(x - cx, z - cz);
          if (d <= r) {
            if (y === 12) {
              set(x, y, z, stemBlock);
            } else {
              const isRim = d > r - 1.1;
              const isDot = isRim && (x === 6 || z === 5 || Math.abs(x - 6) === Math.abs(z - 5));
              set(x, y, z, isDot ? shroomlight : redCapBlock);
            }
          }
        }
      }
    }
    hangLantern(2, 11, 5, regularLantern);
    hangLantern(10, 11, 5, regularLantern);
    hangLantern(6, 11, 10, regularLantern);
  }

  // Balcony porch lantern hanging from front eave
  hangLantern(4, 11, 1, activeLantern);

  return {
    name: "Fungal Canopy Dwelling",
    seatY: 4,
    anchors: {
      front: [6, 8, 0],
      door: [6, 9, 3]
    },
    interiors: [
      {
        min: [4, 9, 4],
        max: [8, 11, 7],
        kind: "quarters"
      }
    ]
  };
}
